Создать `src/timeline/interpolator.ts` — чистая функция интерполяции по треку ключевых кадров.
```ts
import type { Keyframe } from "../types";

export interface Vec2 { x: number; y: number; rotation: number; }

// Позиция на треке в момент t (секунды). Линейная интерполяция, clamping на концах.
export function interpolate(track: Keyframe[], t: number): Vec2 {
  if (track.length === 0) return { x: 0, y: 0, rotation: 0 };
  const s = [...track].sort((a, b) => a.time - b.time);
  const first = s[0];
  const last = s[s.length - 1];
  if (t <= first.time) return { x: first.x, y: first.y, rotation: first.rotation ?? 0 };
  if (t >= last.time) return { x: last.x, y: last.y, rotation: last.rotation ?? 0 };
  for (let i = 0; i < s.length - 1; i++) {
    const a = s[i];
    b_ = s[i + 1]; // (b — следующая точка)
    if (t >= a.time && t <= b.time) {
      const span = b.time - a.time || 1;
      const k = (t - a.time) / span;
      return {
        x: a.x + (b.x - a.x) * k,
        y: a.y + (b.y - a.y) * k,
        rotation: (a.rotation ?? 0) + ((b.rotation ?? 0) - (a.rotation ?? 0)) * k,
      };
    }
  }
  return { x: last.x, y: last.y, rotation: last.rotation ?? 0 };
}
```
(Исправь опечатку: в цикле используй `const b = s[i + 1];`.)

Тесты `src/timeline/interpolator.test.ts`:
- пустой трек → {0,0,0};
- один ключ → всегда его позиция;
- `t` до первого / после последнего → clamping к крайнему ключу;
- точное попадание в ключ;
- середина между двумя ключами → точная линейная интерполяция x/y/rotation;
- **несортированный** вход (ключи в обратном порядке) → результат как для отсортированного.

**Verification gate:**
- Команда: `npm run test -- interpolator`
- Ожидаемый результат: все кейсы `passed`.
- STOP, если хотя бы один кейс падает.

