```ts
import { create } from "zustand";
import type { ObjectData, ProjectSettings, Keyframe, PlayerData, BallData } from "../types";

export const SCHEMA_VERSION = 1;

const DEFAULT_SETTINGS: ProjectSettings = { fps: 24, size: 1080, durationSec: 10 };

function uid(prefix: string) { return `${prefix}-${Math.random().toString(36).slice(2, 9)}`; }

function withSortedTrack<T extends ObjectData>(obj: T): T {
  return { ...obj, track: [...obj.track].sort((a, b) => a.time - b.time) };
}

interface ProjectState {
  settings: ProjectSettings;
  objects: ObjectData[];
  selectedId: string | null;
  currentTime: number;
  isPlaying: boolean;
  addObject: (obj: ObjectData) => void;
  removeObject: (id: string) => void;
  updateObject: (id: string, patch: Partial<ObjectData>) => void;
  setKeyframe: (id: string, kf: Keyframe) => void; // upsert по time
  removeKeyframe: (id: string, time: number) => void;
  select: (id: string | null) => void;
  setCurrentTime: (t: number) => void;
  setPlaying: (p: boolean) => void;
  updateSettings: (patch: Partial<ProjectSettings>) => void;
  loadProject: (p: { settings: ProjectSettings; objects: ObjectData[] }) => void;
}

export const useProjectStore = create<ProjectState>((set) => ({
  settings: DEFAULT_SETTINGS,
  objects: createDefaultProject(),
  selectedId: null,
  currentTime: 0,
  isPlaying: false,
  addObject: (obj) => set((s) => ({ objects: [...s.objects, withSortedTrack(obj)] })),
  removeObject: (id) => set((s) => ({ objects: s.objects.filter((o) => o.id !== id), selectedId: s.selectedId === id ? null : s.selectedId })),
  updateObject: (id, patch) => set((s) => ({ objects: s.objects.map((o) => (o.id === id ? ({ ...o, ...patch }) as ObjectData : o)) })),
  setKeyframe: (id, kf) => set((s) => ({
    objects: s.objects.map((o) => {
      if (o.id !== id) return o;
      const rest = o.track.filter((k) => Math.abs(k.time - kf.time) > 1e-6);
      return { ...o, track: [...rest, kf].sort((a, b) => a.time - b.time) };
    }),
  })),
  removeKeyframe: (id, time) => set((s) => ({
    objects: s.objects.map((o) => o.id !== id ? o : { ...o, track: o.track.filter((k) => Math.abs(k.time - time) > 1e-6) }),
  })),
  select: (id) => set({ selectedId: id }),
  setCurrentTime: (t) => set({ currentTime: t }),
  setPlaying: (p) => set({ isPlaying: p }),
  updateSettings: (patch) => set((s) => ({ settings: { ...s.settings, ...patch } })),
  loadProject: (p) => set({ settings: p.settings, objects: p.objects.map(withSortedTrack), selectedId: null, currentTime: 0, isPlaying: false }),
}));

export function createDefaultProject(): ObjectData[] {
  const player = (n: number, x: number, y: number): PlayerData => ({
    id: uid("p"), kind: "player", visible: true, zIndex: 1,
    number: n, team: "blue", color: "#1565c0", radius: 18,
    track: [{ time: 0, x, y, rotation: 0 }],
  });
  const ball: BallData = {
    id: uid("b"), kind: "ball", visible: true, zIndex: 2,
    radius: 10, color: "#ffffff",
    track: [{ time: 0, x: 100, y: 100, rotation: 0 }],
  };
  return [player(10, 120, 200), player(9, 200, 300), ball];
}
```

