import { Rect, Line } from "react-konva";
import { FIELD } from "../config/field";

export default function Field() {
  const { width, height, background, lineColor } = FIELD;
  return (
    <>
      <Rect x={0} y={0} width={width} height={height} fill={background} />
      <Rect x={0} y={0} width={width} height={height} stroke={lineColor} strokeWidth={3} />
      {/* halfway line */}
      <Line points={[width / 2, 0, width / 2, height]} stroke={lineColor} strokeWidth={2} />
      {/* try lines (упрощённо) */}
      <Line points={[width * 0.1, 0, width * 0.1, height]} stroke={lineColor} strokeWidth={2} />
      <Line points={[width * 0.9, 0, width * 0.9, height]} stroke={lineColor} strokeWidth={2} />
    </>
  );
}
```
