Создай `src/canvas/SceneObject.tsx` — рендер одного объекта в текущий момент времени.
```tsx
import { Group, Circle, Text } from "react-konva";
import { useProjectStore } from "../store/projectStore";
import { interpolate } from "../timeline/interpolator";
import type { PlayerData, BallData, ObjectData } from "../types";

export default function SceneObject({ obj }: { obj: ObjectData }) {
  const currentTime = useProjectStore((s) => s.currentTime);
  const selectedId = useProjectStore((s) => s.selectedId);
  const select = useProjectStore((s) => s.select);
  const setKeyframe = useProjectStore((s) => s.setKeyframe);
  const pos = interpolate(obj.track, currentTime);
  const isSelected = selectedId === obj.id;

  const onDragEnd = (e: { target: { x: () => number; y: () => number } }) => {
    setKeyframe(obj.id, { time: currentTime, x: e.target.x(), y: e.target.y(), rotation: pos.rotation });
  };

  return (
    <Group x={pos.x} y={pos.y} draggable onDragEnd={onDragEnd} onMouseDown={() => select(obj.id)}>
      {obj.kind === "player" && <PlayerShape data={obj as PlayerData} selected={isSelected} />}
      {obj.kind === "ball" && <BallShape data={obj as BallData} selected={isSelected} />}
    </Group>
  );
}

function PlayerShape({ data, selected }: { data: PlayerData; selected: boolean }) {
  return (
    <>
      <Circle radius={data.radius} fill={data.color} stroke={selected ? "#ffeb3b" : "#ffffff"} strokeWidth={selected ? 4 : 2} />
      <Text text={String(data.number)} fontSize={data.radius} fill="#ffffff" align="center" width={data.radius * 2} x={-data.radius} y={-data.radius / 2} />
    </>
  );
}

function BallShape({ data, selected }: { data: BallData; selected: boolean }) {
  return <Circle radius={data.radius} fill={data.color} stroke={selected ? "#ffeb3b" : "#333"} strokeWidth={selected ? 3 : 1} />;
}
```

