  return (
    <Stage width={FIELD.width} height={FIELD.height}>
      <Layer>
        <Field />
        {[...objects].sort((a, b) => a.zIndex - b.zIndex).map((o) => <SceneObject key={o.id} obj={o} />)}
      </Layer>
    </Stage>
  );
}
