Создай `src/timeline/usePlayback.ts` — хук проигрывания.
```ts
import { useEffect, useRef } from "react";
import { useProjectStore } from "../store/projectStore";

export function usePlayback() {
  const isPlaying = useProjectStore((s) => s.isPlaying);
  const setPlaying = useProjectStore((s) => s.setPlaying);
  const setCurrentTime = useProjectStore((s) => s.setCurrentTime);
  const currentTime = useProjectStore((s) => s.currentTime);
  const duration = useProjectStore((s) => s.settings.durationSec);
  const raf = useRef<number | null>(null);
  const last = useRef<number | null>(null);

  useEffect(() => {
    if (!isPlaying) { last.current = null; if (raf.current) cancelAnimationFrame(raf.current); return; }
    const tick = (ts: number) => {
      if (last.current == null) last.current = ts;
      const dt = (ts - last.current) / 1000;
      last.current = ts;
      let next = useProjectStore.getState().currentTime + dt;
      if (next >= duration) { next = 0; } // loop
      setCurrentTime(next);
      raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
    return () => { if (raf.current) cancelAnimationFrame(raf.current); };
  }, [isPlaying, duration, setCurrentTime]);

  return { toggle: () => setPlaying(!isPlaying) };
}
```
(Не включай `currentTime` в зависимости эффекта, чтобы не перезапускать цикл каждый кадр — бери актуальное значение через `getState()`.)
- Кнопка Play/Pause в Timeline. По достижении конца — loop на 0 (для MVP зацикливание приемлемо; при желании останавливайся).

