import { SCHEMA_VERSION } from "../store/projectStore";
import type { ProjectSchema } from "../types";
import type { ObjectData, ProjectSettings } from "../types";

export function toProjectSchema(settings: ProjectSettings, objects: ObjectData[]): ProjectSchema {
  return { schemaVersion: SCHEMA_VERSION, field: "rugby", settings, objects };
}
export function downloadProjectJson(settings: ProjectSettings, objects: ObjectData[]) {
  const data = toProjectSchema(settings, objects);
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob); a.download = "combo.json"; a.click();
}
```

Создай `src/serialization/jsonLoader.ts` с миграцией по версии:
```ts
import { SCHEMA_VERSION } from "../store/projectStore";
import type { ProjectSchema } from "../types";

const migrations: Record<number, (d: any) => any> = {
  // будущие миграции: [2]: (d) => ({ ...d, ... })
};

export function fromProjectSchema(raw: unknown): ProjectSchema {
  if (typeof raw !== "object" || raw === null) throw new Error("Невалидный JSON проекта");
  let data = raw as any;
  const version = Number(data.schemaVersion ?? 0);
  if (!version) throw new Error("Нет schemaVersion");
  for (let v = version; v < SCHEMA_VERSION; v++) {
    const m = migrations[v]; if (m) data = m(data);
  }
  if (Number(data.schemaVersion) > SCHEMA_VERSION) throw new Error(`Файл версии ${data.schemaVersion} новее поддерживаемой ${SCHEMA_VERSION}`);
  return data as ProjectSchema;
}
export function loadProjectFile(file: File): Promise<ProjectSchema> {
  return file.text().then((t) => fromProjectSchema(JSON.parse(t)));
}
```
